<?php
require __DIR__.'/../plugin/core.php';
function check($v,$m){if(!$v)throw new Exception($m);echo "PASS $m\n";}
$p=gca_analyze_policy('https://example.com/cookies/','<main><h1>Informace o cookies</h1><p>Své rozhodnutí můžete kdykoliv upravit kliknutím na tlačítko Nastavení cookies v zápatí.</p></main>');
check($p['checks']['withdrawal']['status']==='pass','recognizes actual paraphrased consent-change instructions');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Souhlas s cookies nelze odvolat. Cookies nelze odmítnout.</p>');
check($p['checks']['withdrawal']['outcome']==='conflict'&&$p['checks']['choice']['outcome']==='conflict','negative instructions do not pass');
$p=gca_analyze_policy('https://example.com/cookies/','<h1>Cookies</h1><p>Žádosti o práci uchováváme 90 dní.</p>');
check($p['checks']['retention']['outcome']==='missing','unrelated personal-data lifetime does not pass cookie duration');
$p=gca_analyze_policy('https://example.com/cookies/','<main><h2>Přehled cookies</h2><table><tr><th>Název cookie</th><th>Účel</th><th>Platnost</th></tr><tr><td>custom_session</td><td>Přihlášení</td><td>Do zavření prohlížeče</td></tr></table></main>');
check($p['checks']['inventory']['status']==='pass','recognizes custom cookie inventory in a table');
check($p['checks']['retention']['status']==='pass','recognizes cookie session lifetime in a table');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Cookies používáme pro analytiku. Dobu uchování neuvedeme.</p>');
check($p['checks']['retention']['outcome']==='missing'&&!str_contains(json_encode($p),'ruční'),'missing information gets an automated bounded outcome');
check($p['checks']['implied_consent']['status']==='pass'&&$p['checks']['implied_consent']['outcome']==='not_detected','absence of problematic wording is not an unmeasured runtime failure');
$documents=[['url'=>'https://example.com/cookies/','_text'=>gca_policy_text('<h1>Cookies</h1><p>Analytické cookies pomáhají měřit návštěvnost.</p>')],['url'=>'https://example.com/tabulka-cookies/','_text'=>gca_policy_text('<p>Cookie _ga se uchovává 13 měsíců.</p>')]];
$p=gca_analyze_policy_documents($documents,[],[]);
check($p['checks']['retention']['status']==='pass'&&$p['checks']['retention']['source_url']===$documents[1]['url'],'linked document evidence has exact provenance');
check(count($p['documents'])===2,'combined assessment records inspected documents');
$q=[['url'=>'https://example.com/','kind'=>'page'],['url'=>'https://example.com/cookies/','kind'=>'policy'],['url'=>'https://example.com/about/','kind'=>'page'],['url'=>'https://example.com/contact/','kind'=>'page'],['url'=>'https://example.com/news/','kind'=>'page']];
$page=['policies'=>[['url'=>'https://example.com/tabulka-cookies/','priority'=>100]],'links'=>[]];
$q=gca_discover_queue($q,1,$page,null);
check(count($q)===5&&$q[2]['url']==='https://example.com/tabulka-cookies/','nested cookie document displaces unvisited general page within cap');
check(count(array_unique(array_column(gca_discover_queue($q,2,$page,null),'url')))===count($q),'queue is deduplicated');
check(gca_cookie_policy_priority('Informace o cookies','https://example.com/informace-o-cookies/')>0,'recognizes information-about-cookies page');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Persistent cookies</p>');
check($p['checks']['retention']['outcome']==='missing','persistent alone is not a stated cookie lifetime');
$p=gca_analyze_policy('https://example.com/cookies/','<p>'.str_repeat('Další text. ',500).'Cookie _ga trvá 13 měsíců.</p>');
check(strlen($p['checks']['retention']['evidence'])<1200&&str_contains($p['checks']['retention']['evidence'],'13 měsíců'),'evidence is bounded and includes the matched statement');
$p=gca_analyze_policy('https://example.com/cookies/','<html><title>Just a moment...</title><body>Checking your browser. Enable cookies.</body></html>');
check($p['checks']['retention']['outcome']==='unavailable','an access challenge is unavailable not missing policy information');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Cookies používáme pro analytiku. Žádosti o práci uchováváme 90 dní.</p><p>Souhlas s odběrem newsletteru můžete odvolat e-mailem.</p>');
check($p['checks']['retention']['outcome']==='missing'&&$p['checks']['withdrawal']['outcome']==='missing','unrelated retention and newsletter withdrawal do not pass cookie checks');
$p=gca_analyze_policy('https://example.com/cookies/','<table><tr><th>Název cookie</th><th>Účel</th><th>Platnost</th></tr><tr><td>custom_session</td><td>Přihlášení</td><td>Neuvedeno</td></tr></table>');
check($p['checks']['retention']['outcome']==='missing','session in a cookie name is not lifetime evidence');
$q=gca_discover_queue([['url'=>'https://example.com/','kind'=>'page']],0,['url'=>'https://www.example.com/','policies'=>[],'links'=>['https://www.example.com/']],null);
check(count($q)===1,'redirected root is not crawled twice');
$p=gca_analyze_policy('https://example.com/cookies/','<h1>Cookies</h1><p>Soubory životopisů uchováváme 90 dní.</p><p>Souhlas se zpracováním osobních údajů můžete kdykoliv odvolat kontaktováním správce.</p>');
check($p['checks']['retention']['outcome']==='missing'&&$p['checks']['withdrawal']['outcome']==='missing','general files and GDPR consent are not cookie evidence');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Nesouhlas s cookies vyjádříte tlačítkem Odmítnout.</p><p>Souhlas s cookies odvoláte v nastavení, návštěvou webu nevyjadřujete souhlas.</p>');
check($p['checks']['choice']['outcome']==='found'&&$p['checks']['withdrawal']['outcome']==='found','legitimate negative consent wording does not erase positive instructions');
$p=gca_analyze_policy_documents([['url'=>'https://example.com/cookies/','_text'=>'Cookies používáme pro analytiku.'],['url'=>'https://example.com/tabulka-cookies/','_text'=>'Just a moment. Checking your browser.']],[],[]);
check($p['checks']['implied_consent']['status']==='unknown'&&$p['checks']['implied_consent']['documents_checked']===1,'inaccessible document cannot become a passed absence check');
$p=gca_analyze_policy('https://example.com/cookies/','<main id="app"></main><script src="app.js"></script>');
check($p['checks']['implied_consent']['outcome']==='unavailable','empty JavaScript-only document is unavailable');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Prohlížeč Google Chrome umožňuje nastavení cookies.</p>',['google-tags','youtube','maps','clarity']);
check(count(array_filter($p['services'],fn($s)=>$s['status']==='pass'))===0,'generic provider name does not document a specific measured service');
$p=gca_analyze_policy('https://example.com/cookies/','<p>Cookies mají různé účely. Používáním webu souhlasíte s cookies.</p>');
check($p['checks']['retention']['status']==='error'&&$p['checks']['implied_consent']['status']==='error','missing documentation and conflicting wording are concrete document defects');
echo "ALL AUTOMATIC POLICY TESTS PASSED\n";
